import{_ as a,o as e,c as l,a3 as i}from"./chunks/framework.D8u9WiMi.js";const m=JSON.parse('{"title":"二十六号的流水账","description":"","frontmatter":{},"headers":[],"relativePath":"listOfEvents/2026/march/26.md","filePath":"listOfEvents/2026/march/26.md"}'),s={name:"listOfEvents/2026/march/26.md"};function o(p,t,r,c,n,_){return e(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="二十六号的流水账" tabindex="-1">二十六号的流水账 <a class="header-anchor" href="#二十六号的流水账" aria-label="Permalink to &quot;二十六号的流水账&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">朱熹《偶成》</p><p>少年易老学难成，一寸光阴不可轻。</p><p>未决池塘春草梦，阶前梧叶已秋生。</p><hr><p>青春的日子极易逝去，学问与事业却很难成功，所以每一寸光阴都绝不能轻易浪费。</p><p>还没从池塘春草般美好的青春梦境中醒来，台前的梧桐叶就已在秋风中沙沙作响，时光转瞬已到秋天。</p></div><p>今天还是主要是工作</p><p>资讯了一下拔牙的诊所，南边有个诊所可以拍片，且可以自己用手机拍片</p><p>周六可以去看看，下午六点下班</p><p>今天看了什么</p><ol><li>隐式转换和显示转换 <ol><li>char、byte、short在计算时，先隐式转换为int再说</li><li>显示转换时取对应的二进制为，多余的直接截断不管</li></ol></li><li>++a，先自增再赋值，a++，先赋值再自增</li><li>原码，反码，补码，为什么一个字节八位可以表现127 - -128，因为0有+0和-0，补码就是负值往下错一位，所以多了个-128</li><li>if</li></ol>',7)])])}const f=a(s,[["render",o]]);export{m as __pageData,f as default};
